package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="notificaciones") public class Notificacion {@Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @Column(name="usuario_id",nullable=false) private UUID usuarioId; private String tipo,categoria,prioridad,titulo; @Column(columnDefinition="TEXT") private String mensaje; @Column(name="entidad_tipo") private String entidadTipo; @Column(name="entidad_id") private UUID entidadId; @Column(name="leida") private boolean leida; @Column(name="leida_en") private LocalDateTime leidaEn; @Column(name="creada_en") private LocalDateTime creadaEn=LocalDateTime.now(); public UUID getId(){return id;}public UUID getEmpresaId(){return empresaId;}public UUID getUsuarioId(){return usuarioId;}public String getCategoria(){return categoria;}public String getPrioridad(){return prioridad;}public String getTitulo(){return titulo;}public String getMensaje(){return mensaje;}public String getEntidadTipo(){return entidadTipo;}public UUID getEntidadId(){return entidadId;}public boolean isLeida(){return leida;}public LocalDateTime getCreadaEn(){return creadaEn;}public void setEmpresaId(UUID x){empresaId=x;}public void setUsuarioId(UUID x){usuarioId=x;}public void setTipo(String x){tipo=x;}public void setCategoria(String x){categoria=x;}public void setPrioridad(String x){prioridad=x;}public void setTitulo(String x){titulo=x;}public void setMensaje(String x){mensaje=x;}public void setEntidadTipo(String x){entidadTipo=x;}public void setEntidadId(UUID x){entidadId=x;}public void setLeida(boolean x){leida=x;}public void setLeidaEn(LocalDateTime x){leidaEn=x;}}
